-- Schema103: offline reviewed Egyptian location names. No address backfill,
-- provider activation, settings change, pricing change or external request.
begin;
set local lock_timeout='5s';
set local statement_timeout='60s';
create table private.delivery_location_governorates (
 code text primary key, name_en text not null, name_ar text not null,
 checkout_name text not null unique, aliases text[] not null, is_active boolean not null
);
create table private.delivery_location_cities (
 code text primary key, governorate_code text not null references private.delivery_location_governorates(code),
 name_en text not null, name_ar text not null, is_active boolean not null
);
create index delivery_location_cities_parent on private.delivery_location_cities(governorate_code);
