-- Search aliases identify a pair only within its evidenced parent.
create function private.delivery_location_key(p_value text) returns text
language sql immutable set search_path='' as $$
 select lower(btrim(regexp_replace(normalize(coalesce(p_value,''),NFKC), '[ـً-ٰٟ]', '', 'g')))
$$;
create function private.delivery_location_supported(p_governorate text,p_city text) returns boolean
language sql stable security definer set search_path='' as $$
 select count(*)=1 from private.delivery_location_cities c
 join private.delivery_location_governorates g on g.code=c.governorate_code
 where g.is_active and c.is_active
 and private.delivery_location_key(p_governorate)=any(array(
  select private.delivery_location_key(n) from unnest(g.aliases||array[g.name_en,g.name_ar,g.checkout_name]) n))
 and private.delivery_location_key(p_city)<>''
 and private.delivery_location_key(p_city)=any(array(
  select private.delivery_location_key(n) from unnest(array[c.name_en,nullif(c.name_ar,'')]) n where n is not null))
$$;
-- A legacy pair is allowed only when already stored by this active customer.
-- No client-controlled legacy flag or foreign-address lookup is accepted.
create function private.delivery_location_owned(p_customer uuid,p_governorate text,p_city text) returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.customer_profiles p where p.id=p_customer and p.is_active and (
  (coalesce(p.state,'')=coalesce(p_governorate,'') and coalesce(p.city,'')=coalesce(p_city,''))
  or exists(select 1 from public.customer_delivery_addresses a where a.customer_id=p.id
    and a.governorate=p_governorate and a.city=p_city)))
$$;
create function private.profile_delivery_location() returns trigger
language plpgsql security definer set search_path='' as $$begin
 if (coalesce(new.city,'')='' and coalesce(new.state,'')='')
  or private.delivery_location_supported(new.state,new.city)
  or private.delivery_location_owned(new.id,new.state,new.city) then return new;end if;
 raise exception 'Select a supported governorate and city.' using errcode='22023';
end $$;
create trigger customer_profile_delivery_location before insert or update of city,state
 on public.customer_profiles for each row execute function private.profile_delivery_location();
create function private.saved_address_delivery_location() returns trigger
language plpgsql security definer set search_path='' as $$begin
 if tg_op='UPDATE' then
  if new.city is not distinct from old.city and new.governorate is not distinct from old.governorate then return new;end if;
 end if;
 if private.delivery_location_supported(new.governorate,new.city) then return new;end if;
 raise exception 'Select a supported governorate and city.' using errcode='22023';
end $$;
create trigger customer_saved_address_delivery_location before insert or update of city,governorate
 on public.customer_delivery_addresses for each row execute function private.saved_address_delivery_location();
create function private.validate_checkout_location(p_customer uuid,p_order jsonb) returns void
language plpgsql security definer set search_path='' as $$begin
 if private.delivery_location_supported(p_order->>'governorate',p_order->>'city')
  or private.delivery_location_owned(p_customer,p_order->>'governorate',p_order->>'city') then return;end if;
 raise exception 'Select a supported governorate and city.' using errcode='22023';
end $$;
-- Preserve intent hashes, exact command recovery and payment/stock contracts.
-- Validate new quotes and commands only after original authorization/recovery.
do $$declare d text;a text;begin
 d:=pg_get_functiondef('public.commerce_checkout_quote(uuid,uuid,jsonb,jsonb)'::regprocedure);
 a:='intent:=private.checkout_intent(p_order,p_items);';
 if (length(d)-length(replace(d,a,'')))/length(a)<>1 then raise exception 'Review quote location boundary.';end if;
 execute replace(d,a,'perform private.validate_checkout_location(p_user_id,p_order);'||a);
 d:=pg_get_functiondef('public.commerce_checkout_command(uuid,uuid,uuid,jsonb,jsonb)'::regprocedure);
 a:='if exists(select 1 from public.customer_orders where user_id=p_user_id and checkout_cart_id=p_cart_id) then';
 if (length(d)-length(replace(d,a,'')))/length(a)<>1 then raise exception 'Review checkout recovery boundary.';end if;
 execute replace(d,a,'perform private.validate_checkout_location(p_user_id,p_order);'||a);
end $$;
revoke all on function private.delivery_location_key(text),private.delivery_location_supported(text,text),
 private.delivery_location_owned(uuid,text,text),private.profile_delivery_location(),
 private.saved_address_delivery_location(),private.validate_checkout_location(uuid,jsonb) from public,anon,authenticated,service_role;
notify pgrst,'reload schema';
commit;
